select
manage.*
from manage manage

    and manage.id = #{id}
    and manage.username = #{username}
    and manage.password = #{password}
    and manage.head_img = #{headImg}
    and manage.nickname like concat('%',#{nickname},'%')
    and manage.create_time = #{createTime}


    limit #{current},#{pageSize}

select count(*) from manage manage

    and manage.id = #{id}
    and manage.username = #{username}
    and manage.password = #{password}
    and manage.head_img = #{headImg}
    and manage.nickname like concat('%',#{nickname},'%')
    and manage.create_time = #{createTime}
